ame = document.createElement(\'iframe\');\r\n        iframe.id = \'introVideo\';\r\n        iframe.src = \"https://player.vimeo.com/video/1110429533?h=5588577461&autoplay=1&muted=1&loop=1&background=1&dnt=1\";\r\n        iframe.frameBorder = \"0\";\r\n        iframe.allowFullscreen = true;\r\n        iframe.sandbox=\"allow-scripts allow-same-origin allow-presentation allow-popups\";\r\n        iframe.allow = \"autoplay; fullscreen\";\r\n        iframe.style.position = \"absolute\";\r\n        iframe.style.zIndex = \"-1\";\r\n        iframe.style.width = \"100%\";\r\n        iframe.style.height = \"100%\";\r\n\r\n        videoContainer.appendChild(iframe);\r\n\r\n        // ✅ pastikan Vimeo.Player dikenali\r\n        const player = new Vimeo.Player(iframe);\r\n\r\n        player.on(\'ended\', function () {\r\n            iframe.style.display = \'none\';\r\n            endImage.style.display = \'block\';\r\n            if (typeof updateImageSource === \"function\") {\r\n                updateImageSource(); // ✅ aman kalau fungsi ada\r\n            }\r\n        });\r\n\r\n    }, 8000);\r\n});\r\n\r\n// YouTube API (kalau mau dipakai)\r\nlet tag = document.createElement(\'script\');\r\ntag.src = \"https://www.youtube.com/iframe_api\";\r\nlet firstScriptTag = document.getElementsByTagName(\'script\')[0];\r\nfirstScriptTag.parentNode.insertBefore(tag, firstScriptTag);\r\n</script>\r\n<script>\r\ndocument.addEventListener(\"DOMContentLoaded\", function () {\r\n    // Initialize Swiper for Testimonial with Auto-Slide\r\n    const swiperTesti = new Swiper(\".swiper-container-testi\", {\r\n        slidesPerView: \"auto\",\r\n        spaceBetween: 20,\r\n        freeMode: true,\r\n        autoplay: {\r\n            delay: 3000, // Ganti angka ini untuk mengatur kecepatan (ms)\r\n            disableOnInteraction: false, // Tetap autoplay setelah user geser manual\r\n        },\r\n        loop: true, // Supaya looping terus tanpa berhenti\r\n        breakpoints: {\r\n           