{\r\n            300: { slidesPerView: 1, spaceBetween: 10 },\r\n            400: { slidesPerView: 1, spaceBetween: 15 },\r\n            500: { slidesPerView: 1, spaceBetween: 15 },\r\n            768: { slidesPerView: 2, spaceBetween: 20 },\r\n            1024: { slidesPerView: 3, spaceBetween: 20 },\r\n        },\r\n    });\r\n\r\n    // Custom button navigation for Testimonial\r\n    const prevBtnTesti = document.getElementById(\"testi-prevBtn\");\r\n    const nextBtnTesti = document.getElementById(\"testi-nextBtn\");\r\n\r\n    if (prevBtnTesti && nextBtnTesti) {\r\n        prevBtnTesti.addEventListener(\"click\", function () {\r\n            swiperTesti.slidePrev();\r\n        });\r\n\r\n        nextBtnTesti.addEventListener(\"click\", function () {\r\n            swiperTesti.slideNext();\r\n        });\r\n    }\r\n});\r\n</script>\r\n\r\n<script>\r\n    function openWhatsApp() {\r\n        let phone = \'6285129370703\';\r\n        let message = \"Halo admin Azolatekno, saya mau tanya layanan web dan SEO. Saya dapat info dari \" + window.location.href;\r\n        let whatsappLink = \"https://wa.me/\" + phone + \"?text=\" + encodeURIComponent(message);\r\n        \r\n        window.open(whatsappLink, \"_blank\");\r\n    }\r\n</script>\r\n    \r\n\r\n    <!-- Footer -->\r\n    <div id=\"cookie-popup\" class=\"cookie-popup hidden\">\n    <p class=\"cookie-text\">\n        Situs ini menggunakan cookie untuk meningkatkan pengalaman Anda. Dengan melanjutkan menggunakan situs, Anda menyetujui penggunaan cookie. \n        <a href=\"https://azolatekno.com/privacy-policy\" class=\"cookie-link\">Baca Kebijakan Privasi kami</a>.\n    </p>\n    <button id=\"accept-cookie\" class=\"cookie-btn\">Terima</button>\n</div>\n\n<footer id=\"footer\">\n  <div class=\"width_100 bg_image1\" >\n    <div class=\"footer-top\">\n    \n      <div class=\"custom-container\" style=\"padding-top: 0 !important;\">\n        <div class=\"row\">\n\n          <div class=\"col-lg-3 col-md-6 footer-