,f);\n})(window,document,\'script\',\'dataLayer\',\'GTM-MBG4JWS\');</script>\n<!-- End Google Tag Manager -->\n  <link rel=\"preload\" href=\"https://azolatekno.com/css/style.min.css\" as=\"style\" onload=\"this.rel=\'stylesheet\'\">\n    <noscript><link rel=\"stylesheet\" href=\"https://azolatekno.com/css/style.min.css?v=1787183067\"></noscript>\n</head>\n<body class=\"\">\n<!-- Google Tag Manager (noscript) -->\n    <!-- Header -->\n    <header id=\"header2\">\n    <div class=\"header-container-home\" >\n      <div id=\"logo2\" class=\"pull-left\">\n        <a href=\"https://azolatekno.com\" class=\"scrollto\" title=\"Logo Azolatekno Web SEO AI\">\n            <picture>\n                <!-- Logo khusus mobile -->\n                <source media=\"(max-width: 768px)\" srcset=\"https://azolatekno.com/img/azolatekno-width-white-mobile.webp\">\n                <!-- Logo default (desktop) -->\n                <source media=\"(min-width: 769px)\" srcset=\"https://azolatekno.com/img/azolatekno-width-white.webp\">\n                <!-- Fallback -->\n                <img src=\"https://azolatekno.com/img/azolatekno-width.webp\" alt=\"Logo Azolatekno Web SEO AI\" loading=\"lazy\">\n            </picture>\n        </a>\n    </div>\n\n\n    <nav id=\"nav-menu-container\">\n            <ul class=\"nav-menu\">\n              <li class=\"menu-active\"><a href=\"https://azolatekno.com\">BERANDA</a></li>\n              <li><a href=\"https://azolatekno.com/layanan\">LAYANAN KAMI</a></li>\n              <li><a href=\"https://azolatekno.com/about-us\">\n                           TENTANG KAMI\n                        </a></li>\n             <li><a href=\"https://azolatekno.com/testimonial\">TESTIMONIAL</a></li>\n             <li><a href=\"https://azolatekno.com/artikel/\">ARTIKEL</a></li>\n            <li class=\"dropdown\">\n                <a href=\"#\" class=\"dropbtn\" onclick=\"return false;\" aria-label=\"dropdown opsi informasi\">\n                    INFORMASI <i class=\"fa fa