elative\"\n    x-data=\"{\n        menu: false,\n        theme: localStorage.theme,\n        darkMode() {\n            this.theme = \'dark\'\n            localStorage.theme = \'dark\'\n            setDarkClass()\n        },\n        lightMode() {\n            this.theme = \'light\'\n            localStorage.theme = \'light\'\n            setDarkClass()\n        },\n        systemMode() {\n            this.theme = undefined\n            localStorage.removeItem(\'theme\')\n            setDarkClass()\n        },\n    }\"\n    @click.outside=\"menu = false\"\n>\n    <button\n        x-cloak\n        class=\"block rounded p-1 hover:bg-gray-100 dark:hover:bg-gray-800\"\n        :class=\"theme ? \'text-gray-700 dark:text-gray-300\' : \'text-gray-400 dark:text-gray-600 hover:text-gray-500 focus:text-gray-500 dark:hover:text-gray-500 dark:focus:text-gray-500\'\"\n        @click=\"menu = ! menu\"\n    >\n        <svg\n    xmlns=\"http://www.w3.org/2000/svg\"\n    fill=\"none\"\n    viewBox=\"0 0 24 24\"\n    stroke-width=\"1.5\"\n    stroke=\"currentColor\"\n    class=\"block h-5 w-5 dark:hidden\"\n>\n    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M12 3v2.25m6.364.386l-1.591 1.591M21 12h-2.25m-.386 6.364l-1.591-1.591M12 18.75V21m-4.773-4.227l-1.591 1.591M5.25 12H3m4.227-4.773L5.636 5.636M15.75 12a3.75 3.75 0 11-7.5 0 3.75 3.75 0 017.5 0z\" />\n</svg>\n        <svg\n    xmlns=\"http://www.w3.org/2000/svg\"\n    fill=\"none\"\n    viewBox=\"0 0 24 24\"\n    stroke-width=\"1.5\"\n    stroke=\"currentColor\"\n    class=\"hidden h-5 w-5 dark:block\"\n>\n    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M21.752 15.002A9.718 9.718 0 0118 15.75c-5.385 0-9.75-4.365-9.75-9.75 0-1.33.266-2.597.748-3.752A9.753 9.753 0 003 11.25C3 16.635 7.365 21 12.75 21a9.753 9.753 0 009.002-5.998z\" />\n</svg>\n    </button>\n\n    <div\n        x-show=\"menu\"\n        class=\"absolute right-0 z-10 flex origin-top-right flex-col rounded-md bg-white shadow-xl ring-1 rin