(1, 'Kaos Polos', 'kaos-polos.webp', 'cotton-combed', 'FBR', 'fabric', 1, 'Kain katun halus, lembut, dan menyerap keringat, ideal untuk kaos nyaman sehari-hari.', 'Y', 1, '2024-10-21 09:35:08', '2024-10-21 09:35:08'),
(2, 'Kaos Print', 'kaos-print.webp', 'cotton-carded', 'FBR', 'fabric', 1, 'Kain katun lebih kasar dibanding combed, tahan lama dan ideal untuk seragam.', 'Y', 2, '2024-10-21 09:35:08', '2024-10-21 09:35:08'),
(3, 'Hoodie', 'hoodie.webp', 'tc-combed', 'FBR', 'fabric', 10, 'Kain campuran tetoron dan katun combed, ideal untuk seragam dan pakaian kasual.', 'Y', 3, '2024-10-21 09:35:08', '2024-10-21 09:35:08'),
(4, 'Kaos Anak', 'kaos-anak.webp', 'lacoste-pique-cvc', 'FBR', 'fabric', 4, 'Pique campuran katun viscose, ideal untuk polo shirt.', 'Y', 4, '2024-10-21 09:35:08', '2024-10-21 09:35:08'),
(5, 'Underwear', 'cd-wanita.webp', 'lacoste-pique-pe', 'FBR', 'fabric', 4, 'Pique berbahan polyester, cocok untuk polo yang tahan lama.', 'Y', 5, '2024-10-21 09:35:08', '2024-10-21 09:35:08'),
(6, 'Underwear Pria', 'cd-pria.webp', 'double-knit-polyester', 'FBR', 'fabric', 2, 'Double Knit Polyester dari Altratex Group, nyaman untuk pakaian kasual.', 'Y', 6, '2024-10-21 09:35:08', '2024-10-21 09:35:08');
